CREATE TRIGGER t_audit_update AFTER UPDATE ON items
BEGIN
  INSERT INTO audit_log(action, item_sku, old_qty, new_qty, changed_at)
  VALUES('update', NEW.sku, OLD.quantity, NEW.quantity, '2026-01-15');
END;
